<style scoped>
.rotate-clock {
    animation: rotation-clockwise 10s infinite linear;
}

@keyframes rotation-clockwise {
    from {
        transform: rotate(0deg);
    }
    to {
        transform: rotate(360deg);
    }
}
.rotate-antiClock {
    animation: rotation-antiClockwise 10s infinite linear;
}

@keyframes rotation-antiClockwise {
    from {
        transform: rotate(0deg);
    }
    to {
        transform: rotate(-360deg);
    }
}
</style>